"""Trim the captured API payloads into tests/unit/fixtures/runs/<run>.json for the triage unit tests.

Only text that the tests never read is shortened (task/prompt/decisions, long summaries, file artifacts);
every value the triage model reads (ids, statuses, times, messages, checks, errors, findings) is kept verbatim.
"""
import json
import sys
from pathlib import Path

API = Path('/tmp/claude-1000/-home-agentops-dev-md-manager/541817b2-200f-49c5-b924-e4e11cf0112a/scratchpad/ux/api')
OUT = Path(sys.argv[1])
TRIM = '(trimmed for the triage fixture)'


def cut(text, limit=160):
    return text if len(text) <= limit else text[:limit - 1].rstrip() + '…'


def trim_inputs(inputs):
    for worker in inputs['workers']:
        worker['task'] = {'text': TRIM, 'truncated': True}
        worker['prompt'] = None
        completion = worker['completion']
        if completion:
            completion['summary'] = cut(completion['summary'])
            completion['open_assumptions'] = [cut(item, 80) for item in completion['open_assumptions'][:2]]
            if completion['untested'] is not None:
                completion['untested'] = [cut(item, 80) for item in completion['untested'][:2]]
            for key in ('verify_yourself',):
                if completion[key] is not None:
                    completion[key] = cut(completion[key], 80)
        if worker['handoff']:
            worker['handoff'] = {'summary': cut(worker['handoff']['summary']), 'open_assumptions': []}
    if inputs['decisions'] is not None:
        inputs['decisions'] = inputs['decisions'].splitlines()[0] + '\n\n' + TRIM + '\n'
    challenge = inputs['challenge']
    if challenge:
        for concern in challenge['concerns']:
            concern['message'] = cut(concern['message'], 100)
            concern['consequence'] = cut(concern['consequence'], 100)
        for key in ('simpler_alternative', 'cheap_experiment'):
            if challenge[key] is not None:
                challenge[key] = cut(challenge[key], 100)
    return inputs


def trim_result(result):
    logs = {check['log_artifact_id'] for check in result['checks']}
    result['artifacts'] = [artifact for artifact in result['artifacts'] if artifact['kind'] != 'file' and (artifact['kind'] != 'log' or artifact['artifact_id'] in logs)]
    result['changed_files'] = []
    if 'files_not_captured' in result:
        result['files_not_captured'] = []
    result['summary'] = cut(result['summary'], 240)
    result['open_assumptions'] = [cut(item, 80) for item in result['open_assumptions'][:2]]
    return result


def trim_review(review):
    for finding in review['findings']:
        finding['message'] = cut(finding['message'], 240)
        if finding['requirement'] is not None:
            finding['requirement'] = cut(finding['requirement'], 120)
    for entry in review['reviewers']:
        entry['findings'] = [finding for finding in review['findings'] if finding['reviewer'] == entry['reviewer_id']]
    return review


RUNS = {
    'skeleton-001': ('project-b', 'skeleton'),
    'skeleton-fixes-001': ('project-b', 'skeleton-fixes'),
    'workflow-guardrails-001': ('md-manager', 'workflow-guardrails'),
}

OUT.mkdir(parents=True, exist_ok=True)
for run, (project, workflow) in RUNS.items():
    bundle = {
        'detail': json.loads((API / f'{run}.detail.json').read_text()),
        'events': json.loads((API / f'{run}.events.json').read_text())['events'],
        'inputs': trim_inputs(json.loads((API / f'{run}.inputs.json').read_text())),
        'review': None,
        'results': {},
    }
    prefix = f'result_api_projects_{project}_workflows_{workflow}_runs_{run}_'
    for path in sorted(API.glob(prefix + '*.json')):
        rest = path.stem[len(prefix):]
        payload = json.loads(path.read_text())
        if rest.startswith('reviews_'):
            bundle['review'] = trim_review(payload)
            continue
        node, attempt = rest[len('results_'):].rsplit('_', 1)
        uri = f'/api/projects/{project}/workflows/{workflow}/runs/{run}/results/{node}/{attempt}'
        bundle['results'][uri] = trim_result(payload)
    (OUT / f'{run}.json').write_text(json.dumps(bundle, indent=1, ensure_ascii=False) + '\n')
    print(run, (OUT / f'{run}.json').stat().st_size, sorted(bundle['results']))

